import{At as bv,C as I_,Ht as ff,Ot as af,T as Jd,Tn as sb,c as Cv,ct as Va}from"./chunk-DoP_Jfy5.js";import"./main-MQUF6YSV.js";import{t as G}from"./chunk-Dm95dFio.js";import{t as v}from"./chunk-DrBhiQSt.js";var u=class s{info=G;backupsFolder=`Dairy Hub Backups`;static ɵfac=function(r){return new(r||s)};static ɵcmp=Jd({type:s,selectors:[[`app-privacy-policy`]],decls:145,vars:9,consts:[[`title`,`Privacy Policy`,`summary`,`A free personal project. Nothing is collected from you for me, and nothing is charged to you.`],[1,`space-y-8`,`text-sm`,`leading-relaxed`,`text-slate-700`],[1,`text-lg`,`font-bold`,`text-slate-900`],[1,`mt-3`,`list-disc`,`space-y-2`,`pl-5`],[1,`mt-3`],[1,`mt-4`,`font-semibold`,`text-slate-900`],[1,`mt-2`],[1,`rounded`,`bg-slate-100`,`px-1.5`,`py-0.5`,`font-mono`,`text-xs`,`text-slate-800`],[`href`,`https://myaccount.google.com/permissions`,`target`,`_blank`,`rel`,`noopener noreferrer`,1,`font-semibold`,`text-blue-600`,`hover:text-blue-500`,`dark:text-blue-400`,`dark:hover:text-blue-300`],[`href`,`https://developers.google.com/terms/api-services-user-data-policy`,`target`,`_blank`,`rel`,`noopener noreferrer`,1,`font-semibold`,`text-blue-600`,`hover:text-blue-500`,`dark:text-blue-400`,`dark:hover:text-blue-300`]],template:function(r,n){r&1&&(Va(0,`app-legal-page`,0)(1,`div`,1)(2,`section`)(3,`h2`,2),I_(4,`1. The short version`),af(),Va(5,`ul`,3)(6,`li`),I_(7),af(),Va(8,`li`),I_(9,` I do not run analytics, advertising, tracking pixels or profiling, and I do not sell or share your information. `),af(),Va(10,`li`),I_(11,` I do not take your data for myself. What exists is what you enter, kept in your own account so the app can work for you. `),af(),Va(12,`li`),I_(13,` You can export or delete your data at any time, and you can stop using the app whenever you like. `),af()()(),Va(14,`section`)(15,`h2`,2),I_(16,`2. Who runs this app`),af(),Va(17,`p`,4),I_(18),af(),Va(19,`p`,4),I_(20),af()(),Va(21,`section`)(22,`h2`,2),I_(23,` 3. What I do not collect `),af(),Va(24,`ul`,3)(25,`li`),I_(26,`No analytics, usage tracking, heatmaps or crash profiling.`),af(),Va(27,`li`),I_(28,`No advertising identifiers, pixels or remarketing lists.`),af(),Va(29,`li`),I_(30,` No access to your device's contacts, address book or social accounts. `),af(),Va(31,`li`),I_(32,`No payment card, bank or billing details.`),af(),Va(33,`li`),I_(34,`No marketing or newsletter subscriptions.`),af()(),Va(35,`p`,4),I_(36,` I do not read your business records for my own purposes, and I do not use them to build profiles or train advertising systems. `),af()(),Va(37,`section`)(38,`h2`,2),I_(39,` 4. What is stored to run the app `),af(),Va(40,`p`,4),I_(41,` The app cannot work without some information. This is the complete list, and it exists only to provide the service to you: `),af(),Va(42,`h3`,5),I_(43,` 4.1 Account information `),af(),Va(44,`p`,6),I_(45,` When you create an account or sign in with Google, I receive your email address, your display name and a unique account identifier. Authentication is handled by Google Firebase Authentication. I never receive or store your Google password. `),af(),Va(46,`h3`,5),I_(47,` 4.2 Business records you enter `),af(),Va(48,`p`,6),I_(49,` The information you record in the app — milkman details, daily milk entries, milk rates, payments and your application settings — is stored in your account so it is available on every device you sign in from. It is your data, not mine. `),af(),Va(50,`h3`,5),I_(51,` 4.3 Security and device information `),af(),Va(52,`p`,6),I_(53,` To help you review account activity, the app records sign-in sessions and trusted devices, including a timestamp, the browser's user agent string, and the IP address and approximate geographic location reported for that connection. The approximate location is obtained by sending the request's IP address to the third-party service ipwho.is (see section 7). `),af(),Va(54,`h3`,5),I_(55,`4.4 Preferences`),af(),Va(56,`p`,6),I_(57,` Formatting choices such as your currency and colour theme are stored with your settings so the app displays consistently on every device. `),af(),Va(58,`h3`,5),I_(59,`4.5 Contact form`),af(),Va(60,`p`,6),I_(61,` The name, email address, optional phone number and message you enter on the contact page are used only to reply to you. They are not added to a mailing list and are not used for marketing. `),af()(),Va(62,`section`)(63,`h2`,2),I_(64,` 5. Google Drive backup `),af(),Va(65,`p`,4),I_(66,` The optional backup feature connects to your personal Google Drive. Access is requested through Google Identity Services using the scope `),Va(67,`code`,7),I_(68,`https://www.googleapis.com/auth/drive.file`),af(),I_(69,`. `),af(),Va(70,`ul`,3)(71,`li`),I_(72,` This scope lets the app see, create and delete `),Va(73,`strong`),I_(74,`only the files and folders it creates itself`),af(),I_(75,`. It cannot read, list or modify any other file in your Drive. `),af(),Va(76,`li`),I_(77,` When you create a backup, the app creates a folder named `),Va(78,`em`),I_(79),af(),I_(80,` in your Drive and uploads a JSON snapshot of your database there. Backups are named with a timestamp, for example `),Va(81,`code`,7),I_(82,`dairy-backup-2026-10-02T09-30-00.json`),af(),I_(83,`. `),af(),Va(84,`li`),I_(85,` Restoring and deleting backups also act only on those files. `),af(),Va(86,`li`),I_(87,` The OAuth access token is stored in your browser's local storage so the connection survives a page refresh. It expires after roughly one hour. Tokens are sent only to Google's API endpoints and are never transmitted to me. `),af(),Va(88,`li`),I_(89),Va(90,`a`,8),I_(91,` myaccount.google.com/permissions `),af(),I_(92,`. `),af()()(),Va(93,`section`)(94,`h2`,2),I_(95,` 6. Google API Services User Data Policy `),af(),Va(96,`p`,4),I_(97),Va(98,`a`,9),I_(99,` Google API Services User Data Policy `),af(),I_(100,`, including the Limited Use requirements. `),af(),Va(101,`p`,4),I_(102,` In particular, Drive data obtained through the scope above is used solely to provide the backup and restore feature you explicitly request. It is not used for advertising, is not sold, and is not transferred to third parties except as needed to provide that feature or to comply with the law. `),af()(),Va(103,`section`)(104,`h2`,2),I_(105,` 7. Service providers `),af(),Va(106,`p`,4),I_(107,` The app relies on the following third parties. Each processes data only as needed to provide its service, and none of them receives payment from you: `),af(),Va(108,`ul`,3)(109,`li`)(110,`strong`),I_(111,`Google Firebase`),af(),I_(112,` (Authentication, Cloud Firestore and Cloud Storage) — hosts your account and your business records. `),af(),Va(113,`li`)(114,`strong`),I_(115,`Google Drive API`),af(),I_(116,` — stores the backups you choose to create, in your own Drive. `),af(),Va(117,`li`)(118,`strong`),I_(119,`ipwho.is`),af(),I_(120,` — receives the IP address of a sign-in request in order to return an approximate city, region and country for your security activity list. `),af()(),Va(121,`p`,4),I_(122,` Data is transmitted over HTTPS. Firebase and Google Drive data are encrypted in transit by Google. `),af()(),Va(123,`section`)(124,`h2`,2),I_(125,` 8. Storage on your device `),af(),Va(126,`p`,4),I_(127,` The app keeps a small amount of data in your browser's local storage: the restored sign-in session, your theme choice, and — only if you connect Google Drive — the short-lived OAuth token. These stay on your device and can be cleared by clearing site data or by signing out. `),af()(),Va(128,`section`)(129,`h2`,2),I_(130,` 9. Your data, export and deletion `),af(),Va(131,`p`,4),I_(132,` Your records belong to you. You can export your full database to CSV, PDF or JSON at any time, and you can delete backups individually from the Data Management settings. `),af(),Va(133,`p`,4),I_(134),af()(),Va(135,`section`)(136,`h2`,2),I_(137,`10. Children`),af(),Va(138,`p`,4),I_(139),af()(),Va(140,`section`)(141,`h2`,2),I_(142,` 11. Changes to this policy `),af(),Va(143,`p`,4),I_(144,` I may update this policy as the app changes. Material changes will be reflected in the "Last updated" date above. `),af()()()()),r&2&&(sb(7),ff(` `,n.info.appName,` is a free personal project. I do not charge you and I do not take payment details from you. `),sb(11),bv(` `,n.info.appName,` is an independent personal project run by `,n.info.operatorName,`, an individual developer. It is not a company, there is no business entity behind it, and there is no team receiving your information. `),sb(2),ff(` You use `,n.info.appName,` with your own account. The business records you enter are yours. This policy explains where they are stored and when they leave your device. `),sb(59),Cv(n.backupsFolder),sb(10),ff(` You can disconnect at any time from the app's Data Management settings, which clears the stored token, or by revoking access for `,n.info.appName,` at `),sb(8),ff(` `,n.info.appName,`'s use and transfer of information received from Google APIs to any other app adheres to the `),sb(37),ff(` Deleting your account removes your records from `,n.info.appName,`. Copies of exported or backed-up files that you saved to your own device or Drive remain under your control and must be deleted by you. `),sb(5),ff(` `,n.info.appName,` is a business tool and is not directed to children. I do not knowingly collect information from children. `))},dependencies:[v],encapsulation:2})};export{u as PrivacyPolicyComponent};